package com.hirain.aiagent.rag.policy;
import com.hirain.aiagent.rag.model.RetrievalEvidence;import java.util.*;
/** Evidence V1 采用 Unicode 词元估算（CJK 字元、Latin/数字词元），不是字符数截断。 */
public final class EvidenceBudgetPolicy { private final int maxTokens; public EvidenceBudgetPolicy(int maxTokens){this.maxTokens=maxTokens;} public List<RetrievalEvidence> select(List<RetrievalEvidence> values){List<RetrievalEvidence> out=new ArrayList<>();int used=0;for(RetrievalEvidence value:values){int tokens=estimate(value.content());if(used+tokens>maxTokens)continue;out.add(value);used+=tokens;}return List.copyOf(out);} public static int estimate(String text){if(text==null||text.isBlank())return 0;int count=0;boolean latin=false;for(int i=0;i<text.length();){int cp=text.codePointAt(i);i+=Character.charCount(cp);if(Character.UnicodeScript.of(cp)==Character.UnicodeScript.HAN){count++;latin=false;}else if(Character.isLetterOrDigit(cp)){if(!latin){count++;latin=true;}}else latin=false;}return count;} }
